import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int bufLen, bufPtr;

    static int read() throws IOException {
        if (bufPtr == bufLen) {
            bufLen = System.in.read(BUF, 0, BUF.length);
            bufPtr = 0;
            if (bufLen <= 0) return -1;
        }
        return BUF[bufPtr++];
    }

    static String next() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = read();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        String s = next();
        // First/last position of each letter, and the index of the equal-letter run containing each.
        int[] first = new int[26], last = new int[26], firstRun = new int[26], lastRun = new int[26];
        Arrays.fill(first, -1);
        int run = 0;
        char previous = 0;
        for (int i = 0; i < s.length(); i++) {
            char ch = s.charAt(i);
            int c = ch - 'a';
            if (ch != previous) {
                run++;
                previous = ch;
            }
            if (first[c] < 0) {
                first[c] = i;
                firstRun[c] = run;
            }
            last[c] = i;
            lastRun[c] = run;
        }
        int answer = -1;
        for (int c = 0; c < 26; c++)
            if (first[c] >= 0 && firstRun[c] != lastRun[c]) answer = Math.max(answer, last[c] - first[c]);
        System.out.println(answer);
    }
}

