import (
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

func nextToken() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	s := nextToken()
	// First/last position of each letter, and the index of the equal-letter run containing each.
	var first, last, firstRun, lastRun [26]int
	for c := range first {
		first[c] = -1
	}
	run := 0
	var previous byte
	for i, ch := range s {
		c := ch - 'a'
		if ch != previous {
			run++
			previous = ch
		}
		if first[c] < 0 {
			first[c] = i
			firstRun[c] = run
		}
		last[c] = i
		lastRun[c] = run
	}
